#!/usr/bin/env python3
import sys
import re

def safe_eval(expr):
    """Safely evaluate a mathematical expression with +, -, *, /, and parentheses."""
    # Check for any unsafe characters
    # Allow only digits, operators, parentheses, spaces, and decimal points
    if not re.match(r'^[\d\s+\-*/().]+$', expr):
        raise ValueError("Invalid characters in expression")

    # Use Python's eval but restrict the namespace
    return eval(expr, {"__builtins__": {}}, {})

def main():
    if len(sys.argv) < 2:
        print("Usage: calc <expression>")
        sys.exit(1)

    # Join all arguments after "calc"
    expr = ' '.join(sys.argv[1:])

    try:
        result = safe_eval(expr)
        # Format the result: show as integer if it's a whole number, otherwise as float
        if isinstance(result, float) and result == int(result):
            print(int(result))
        else:
            print(result)
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
